// Пин для Trig (запуск измерения)
const int trigPin = 9;
// Пин для Echo (приём отражённого сигнала)
const int echoPin = 8;

// Таймаут ожидания эхо-сигнала (в микросекундах)
// Для SRF05 максимум ~ 30 мс (около 5 метров)
const unsigned long timeout = 30000UL;

void setup() {
  Serial.begin(9600);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  // Небольшая задержка для стабилизации питания
  delay(100);
}

void loop() {
  // 1. Отправляем короткий импульс на Trig (не менее 10 мкс)
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // 2. Измеряем длительность высокого уровня на Echo
  unsigned long duration = pulseIn(echoPin, HIGH, timeout);

  // 3. Если сигнал не пришёл (таймаут) – выводим ошибку
  if (duration == 0) {
    Serial.println("Ошибка: объект вне диапазона");
  } else {
    // 4. Пересчёт в расстояние (см):
    //    скорость звука ~ 343 м/с = 34300 см/с
    //    расстояние = (время * скорость) / 2 (туда-обратно)
    //    время в мкс, поэтому: расстояние (см) = duration * 0.0343 / 2
    float distance = duration * 0.01715;  // 0.0343 / 2 = 0.01715
    // Ограничим разумный диапазон (2 см – 400 см)
    if (distance < 2.0) distance = 2.0;
    if (distance > 400.0) distance = 400.0;

    Serial.print("Расстояние: ");
    Serial.print(distance);
    Serial.println(" см");
  }

  // Задержка между измерениями (не менее 50 мс)
  delay(100);
}
